// ============================================================================
// schema.prisma — Property model (lines 329-419)
// ============================================================================
model Property {
  id               String   @id @default(cuid())
  userId           String   // Multi-tenant: which investor owns this property lead
  address          String
  city             String
  state            String
  zip              String
  county           String?  // <-- string name "Duval", NOT FIPS
  apn              String?  // Assessor Parcel Number
  ownerName        String?

  // Property details
  propertyType     String?
  bedrooms         Int?
  bathrooms        Int?
  squareFeet       Int?
  lotSize          Int?
  yearBuilt        Int?

  // Financial
  assessedValue    Float?
  taxAmount        Float?
  lastSaleDate     String?
  lastSalePrice    Float?
  estimatedValue   Float?

  // Distress flags
  foreclosure      Boolean  @default(false)
  preForeclosure   Boolean  @default(false)
  taxDelinquent    Boolean  @default(false)
  vacant           Boolean  @default(false)
  bankruptcy       Boolean  @default(false)
  absenteeOwner    Boolean  @default(false)

  // NOTE: NO latitude/longitude columns!
  // NOTE: NO countyFips column!

  // Source tracking
  dataSource       String
  sourceId         String?
  enriched         Boolean  @default(false)

  metadata         String?

  user             User           @relation(fields: [userId], references: [id], onDelete: Cascade)
  dataPoints       PropertyDataPoint[]

  @@unique([userId, address, city, state, zip])
  @@index([userId])
  @@index([score])
  @@index([city, state])
}

// ============================================================================
// schema.prisma — Parcel model (lines 1647-1693)
// ============================================================================
model Parcel {
  id                  String   @id @default(cuid())
  countyFips          String                 // "12031"  <-- FIPS, not name
  apn                 String                 // PARCEL_ID from the roll
  state               String                 // "FL"

  ownerName           String?
  ownerMailingAddress String?
  situsAddress        String?
  situsCity           String?
  situsState          String?
  situsZip            String?

  marketValue         Float?                 // JV (just value)
  assessedValue       Float?
  landValue           Float?

  propertyType        String?
  yearBuilt           Int?
  squareFeet          Int?
  lotSize             Float?

  lastSalePrice       Float?
  lastSaleYear        Int?

  // <-- Parcel HAS lat/lng (Property does NOT)
  latitude            Float?
  longitude           Float?

  source              String
  dataVintage         String?
  fetchedAt           DateTime @default(now())

  @@unique([countyFips, apn])             // <-- the natural join key
  @@index([countyFips])
  @@index([situsZip])
  @@index([state])
}

// ============================================================================
// schema.prisma — Lien model (lines 1558-1584)
// ============================================================================
model Lien {
  id              String   @id @default(cuid())
  countyFips      String                 // join part 1
  apn             String?                // join part 2 (nullable!)
  lienCategory    String                 // "mechanics" | "hoa" | "tax" | ...
  recordingDate   DateTime
  filingDate      DateTime?
  amount          Float?
  defendantName   String?                // property owner being lienned
  documentNumber  String?
  source          String
  capturedAt      DateTime @default(now())

  @@unique([countyFips, documentNumber, source])
  @@index([countyFips, apn, lienCategory, recordingDate])
  @@index([apn])
  @@index([lienCategory, recordingDate])
}

// ============================================================================
// schema.prisma — PropertyDataPoint (the ONLY existing bridge)
// ============================================================================
model PropertyDataPoint {
  id          String   @id @default(cuid())
  propertyId  String   // <-- requires a Property row to exist
  field       String   // "tax_delinquent" | "open_mortgage_balance" | ...
  value       String   @db.Text
  source      String   // "scraper:fl-duval-treasurer" | "batchdata" | ...
  fetchedAt   DateTime @default(now())
  expiresAt   DateTime?
  confidence  Float?

  property    Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)

  @@unique([propertyId, field, source])
}

